-- Download sky-data modules from this GitHub repository.
local REPO='https://raw.githubusercontent.com/lyn4x-js/New-/main/'
local function loadSkyPart(filename)
 local ok,body=pcall(function() return game:HttpGet(REPO..filename) end)
 if not ok then error('[tornhub] Could not download '..filename..': '..tostring(body)) end
 local fn,err=loadstring(body)
 if not fn then error('[tornhub] Invalid '..filename..': '..tostring(err)) end
 local success,result=pcall(fn)
 if not success or type(result)~='table' then error('[tornhub] Failed to load '..filename..': '..tostring(result)) end
 return result
end
local EXTRA_SKY_B64={}
for _,filename in ipairs({'skies_1.lua','skies_2.lua'}) do
 for key,value in pairs(loadSkyPart(filename)) do
  EXTRA_SKY_B64[key]=EXTRA_SKY_B64[key] or {}
  for face,bytes in pairs(value) do EXTRA_SKY_B64[key][face]=bytes end
 end
end
local alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local lookup={} for i=1,#alphabet do lookup[alphabet:sub(i,i)]=i-1 end
local function decode(s)
 local out={}
 for i=1,#s,4 do
  local a=lookup[s:sub(i,i)] or 0; local b=lookup[s:sub(i+1,i+1)] or 0
  local c=lookup[s:sub(i+2,i+2)]; local d=lookup[s:sub(i+3,i+3)]
  local v=a*262144+b*4096+(c or 0)*64+(d or 0)
  out[#out+1]=string.char(math.floor(v/65536)%256)
  if c then out[#out+1]=string.char(math.floor(v/256)%256) end
  if d then out[#out+1]=string.char(v%256) end
 end
 return table.concat(out)
end
local function fileAsset(key,bytes)
 if not writefile or not G then return nil,'Delta file/custom asset API unavailable' end
 local ext=bytes:sub(1,3)=='\255\216\255' and '.jpg' or bytes:sub(1,4)=='RIFF' and '.webp' or '.png'
 local path='four_sky_'..key..ext
 local ok,err=pcall(writefile,path,bytes); if not ok then return nil,tostring(err) end
 local yes,asset=pcall(G,path); if not yes then return nil,tostring(asset) end
 return asset
end

