local function getExtraPack(name)
 if name=='Blackhole' then return BLACKHOLE_ASSETS end
 local src=EXTRA_PACK_URLS[name]
 if not src then return nil,'Unknown sky pack' end
 local result={}
 for _,f in ipairs(faces) do
  local link=src[f]
  local bytes
  if link:sub(1,9)=='embedded:' then
   local key=link:sub(10)
   local encoded=EMBEDDED_EXTRA[key]
   if not encoded then return nil,'Missing embedded texture '..key end
   bytes=decode(encoded)
  else
   local ok,data=pcall(function() return Http:HttpGet(link) end)
   if not ok or type(data)~='string' or #data<64 then return nil,'Download failed for '..name..' '..f end
   bytes=data
  end
  local asset,err=fileAsset(name..f,bytes)
  if not asset then return nil,err end
  result[f]=asset
 end
 return result
end

local function assetsFor(name)
 if state.cache[name] then return state.cache[name] end
 local result={}
 if name=='Blackhole' or EXTRA_PACK_URLS[name] then
  local a,err=getExtraPack(name); if not a then return nil,err end
  result=a
 elseif name=='CoolBlack' then
  for _,f in ipairs(faces) do result[f]='rbxassetid://7658055825' end
 elseif EXTRA_SKY_B64[name] then
  for _,f in ipairs(faces) do
   local asset,err=fileAsset(name..f,decode(EXTRA_SKY_B64[name][f])); if not asset then return nil,err end
   result[f]=asset
  end
 elseif name=='Makima' then
  for _,f in ipairs(faces) do
   local asset,err=fileAsset('Makima'..f,decode(MAKIMA_B64[f])); if not asset then return nil,err end
   result[f]=asset
  end
 elseif name=='Breakcore' then
  local asset,err=fileAsset('breakcore',decode(BREAKCORE_B64)); if not asset then return nil,err end
  for _,f in ipairs(faces) do result[f]=asset end
 else
  for _,f in ipairs(faces) do
   local ok,bytes=pcall(function() return Http:HttpGet(urls[name][f]) end)
   if not ok or type(bytes)~='string' or #bytes<64 then return nil,'Failed to download '..f end
   local asset,err=fileAsset(name..f,bytes); if not asset then return nil,err end
   result[f]=asset
  end
 end
 state.cache[name]=result
 return result
end
local function putSky(name)
 if state.closed or name~=state.active then return end
 local a=state.cache[name]; if not a then return end
 if state.applying then return end
 state.applying=true
 local ok,err=pcall(function()
  local sky=Instance.new('Sky'); sky.Name='TornHubSky_'..name
  for _,f in ipairs(faces) do sky['Skybox'..f]=a[f] end
  -- Do not remove the old sky until all six faces have been assigned.
  sky.Parent=Lighting
  for _,v in ipairs(Lighting:GetChildren()) do
   if v:IsA('Sky') and v~=sky then v:Destroy() end
  end
 end)
 state.applying=false
 if not ok then warn('[tornhub] Sky apply failed: '..tostring(err)) end
end
