local function selectSky(name,label)
 state.serial=state.serial+1
 local ticket=state.serial
 status.Text='Loading '..label..'...'
 task.spawn(function()
  local ok,a,err=pcall(assetsFor,name)
  if state.closed or ticket~=state.serial then return end
  if not ok or not a then
   status.Text='Error: '..tostring(ok and err or a)
   warn('[tornhub] '..status.Text)
   return
  end
  state.active=name
  putSky(name)
  status.Text='Active: '..label
  -- Reapply once after the initial selection to accommodate transitions.
  task.delay(1,function()
   if not state.closed and state.active==name then putSky(name) end
  end)
 end)
end
