 local b=Instance.new('TextButton')
 b.Name='Sky_'..item[2]; b.Size=UDim2.new(1,-6,0,33)
 b.BackgroundColor3=Color3.fromRGB(26,27,32); b.BackgroundTransparency=0.12
 b.BorderSizePixel=0; b.TextColor3=Color3.fromRGB(232,232,235)
 b.Font=Enum.Font.GothamMedium; b.TextSize=12
 b.Text='   '..item[1]; b.TextXAlignment=Enum.TextXAlignment.Left
 b.LayoutOrder=i; b.ZIndex=5; b.Parent=list
 Instance.new('UICorner',b).CornerRadius=UDim.new(0,6)
 local accent=Instance.new('Frame'); accent.Size=UDim2.fromOffset(2,15)
 accent.Position=UDim2.new(0,5,0.5,-7); accent.BackgroundColor3=orange
 accent.BorderSizePixel=0; accent.ZIndex=6; accent.Parent=b
 skyButtons[#skyButtons+1]={button=b,label=item[1]}
 b.MouseButton1Click:Connect(function() selectSky(item[2],item[1]) end)
end
search:GetPropertyChangedSignal('Text'):Connect(function()
 local q=search.Text:lower()
 for _,entry in ipairs(skyButtons) do
  entry.button.Visible=(q=='' or entry.label:lower():find(q,1,true)~=nil)
 end
end)
local childConn=Lighting.ChildAdded:Connect(function(obj)
 if state.closed or state.applying or not state.active or not obj:IsA('Sky')
  or obj.Name=='TornHubSky_'..state.active then return end
 task.delay(.2,function()
  if not state.closed and not state.applying and state.active then
   putSky(state.active)
  end
 end)
end)
function state.Close()
 if state.closed then return end
 state.closed=true; state.serial=state.serial+1
 childConn:Disconnect(); gui:Destroy()
 if env.FourSkySwitcher==state then env.FourSkySwitcher=nil end
end
close.MouseButton1Click:Connect(function()
 frame.Visible=false; reopen.Visible=true
end)
reopen.MouseButton1Click:Connect(function()
 frame.Visible=true; reopen.Visible=false
end)
pcall(function()
 game:GetService('StarterGui'):SetCore('SendNotification',{
  Title='tornhub',Text='27 skies listed. Close with X; reopen using tornhub.',Duration=5
 })
end)
print('[tornhub] Ready: 27 skies')
